style.css:
@-moz-document domain("play.pokemonshowdown.com") {
/* Fundo geral */
  body, .ps-room {
    background-color: #f5f5f5 !important;
    color: #111 !important;
    font-family: 'Verdana', sans-serif !important;
  }

  /* Caixa principal da batalha */
  .battle {
    background: linear-gradient(to bottom, #fafafa 0%, #e0e0e0 100%) !important;
    border: 2px solid #ccc !important;
    box-shadow: 0 0 10px #bbb inset !important;
  }

  /* Campo de batalha */
  .battlecanvas {
    background-color: #ddd !important;
    background-image: radial-gradient(circle at center, #eee 0%, #ccc 100%) !important;
    border-radius: 8px !important;
    border: 1px solid #bbb !important;
  }

  /* Chat */
  .chat {
    background-color: #f0f0f0 !important;
    border-left: 1px solid #ccc !important;
    color: #000 !important;
  }

  /* Barra de HP */
  .hpbar {
    border: 1px solid #888 !important;
    border-radius: 6px !important;
    background-color: #fff !important;
  }

  .hpbar .hptext {
    color: #111 !important;
    font-weight: bold !important;
    text-shadow: none !important;
  }

  .hpbar .bar {
    border-radius: 6px !important;
    background: linear-gradient(to right, #5ce65c, #4ac04a) !important;
  }

  /* Botões base */
  button, .button, .teamicons {
    background-color: #ffffff !important;
    border: 1px solid #999 !important;
    border-radius: 6px !important;
    color: #000 !important;
    font-weight: bold !important;
    transition: 0.2s ease;
  }

  button:hover, .button:hover {
    background-color: #eaeaea !important;
  }

  /* Tipos de ataque com contorno */
  /* Elétrico */
  button[name*="Thunder"], button[name*="Volt"], button[name*="Electric"], button[name*="Zap"], button[name*="Bolt"] {
    box-shadow: 0 0 8px #ffeb3b !important;
    border-color: #ffeb3b !important;
  }

  /* Fogo */
  button[name*="Flame"], button[name*="Fire"], button[name*="Burn"], button[name*="Heat"] {
    box-shadow: 0 0 8px #ff9800 !important;
    border-color: #ff9800 !important;
  }

  /* Água */
  button[name*="Water"], button[name*="Hydro"], button[name*="Aqua"], button[name*="Surf"] {
    box-shadow: 0 0 8px #2196f3 !important;
    border-color: #2196f3 !important;
  }

  /* Planta */
  button[name*="Leaf"], button[name*="Vine"], button[name*="Seed"], button[name*="Grass"], button[name*="Bloom"] {
    box-shadow: 0 0 8px #4caf50 !important;
    border-color: #4caf50 !important;
  }

  /* Gelo */
  button[name*="Ice"], button[name*="Frost"], button[name*="Freeze"], button[name*="Blizzard"] {
    box-shadow: 0 0 8px #00bcd4 !important;
    border-color: #00bcd4 !important;
  }

  /* Lutador */
  button[name*="Punch"], button[name*="Kick"], button[name*="Chop"], button[name*="Strike"] {
    box-shadow: 0 0 8px #d32f2f !important;
    border-color: #d32f2f !important;
  }

  /* Fantasma */
  button[name*="Shadow"], button[name*="Ghost"], button[name*="Specter"] {
    box-shadow: 0 0 8px #9c27b0 !important;
    border-color: #9c27b0 !important;
  }

  /* Venenoso */
  button[name*="Poison"], button[name*="Toxic"], button[name*="Sludge"] {
    box-shadow: 0 0 8px #8e24aa !important;
    border-color: #8e24aa !important;
  }

  /* Terrestre */
  button[name*="Earth"], button[name*="Mud"], button[name*="Ground"], button[name*="Quake"] {
    box-shadow: 0 0 8px #a67c52 !important;
    border-color: #a67c52 !important;
  }

  /* Pedra */
  button[name*="Rock"], button[name*="Stone"], button[name*="Boulder"] {
    box-shadow: 0 0 8px #b0bec5 !important;
    border-color: #b0bec5 !important;
  }

  /* Psíquico */
  button[name*="Psychic"], button[name*="Mind"], button[name*="Psy"], button[name*="Dream"] {
    box-shadow: 0 0 8px #e91e63 !important;
    border-color: #e91e63 !important;
  }

  /* Dragão */
  button[name*="Dragon"], button[name*="Draco"], button[name*="Roar"] {
    box-shadow: 0 0 8px #3f51b5 !important;
    border-color: #3f51b5 !important;
  }

  /* Inseto */
  button[name*="Bug"], button[name*="String"], button[name*="Web"] {
    box-shadow: 0 0 8px #8bc34a !important;
    border-color: #8bc34a !important;
  }

  /* Sombrio */
  button[name*="Dark"], button[name*="Night"], button[name*="Evil"] {
    box-shadow: 0 0 8px #212121 !important;
    border-color: #212121 !important;
  }

  /* Fada */
  button[name*="Fairy"], button[name*="Moon"], button[name*="Kiss"] {
    box-shadow: 0 0 8px #f48fb1 !important;
    border-color: #f48fb1 !important;
  }

  /* Painel de comandos */
  .controls {
    background-color: #f7f7f7 !important;
    border-top: 1px solid #ccc !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px !important;
  }
  ::-webkit-scrollbar-thumb {
    background: #aaa !important;
    border-radius: 8px !important;
  }
}
